// Parallelism: Utilizing all available cores for CPU-bound work
List<Integer> numbers = IntStream.range(0, 1000000).boxed().toList();
long sum = numbers.parallelStream()
                  .mapToLong(i -> i * 2L)
                  .sum();

// Concurrency: Handling I/O-bound tasks with Virtual Threads
try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
    IntStream.range(0, 1000).forEach(i -> executor.submit(() -> {
        Thread.sleep(100); // Simulated I/O block
        return i;
    }));
}
